// Generates an array of observations placed evenly on a circle of given radius and center. The caller is responsible for freeing the returned array.
observation *helper_generate_observations_circle(size_t num_points, double radius, double center_x, double center_y) {
    observation *arr = (observation *)malloc(num_points * sizeof(observation));
